import {mountDiary,mountSharedDiary,readDiaryLink,mountReminderSummary,mountProjectIdentity} from './diary.mjs?v=20261118-contractor3';
import {STAGES,CATEGORIES,KINDS,NEIGHBORHOODS,empty,validate,command,totals,scenario,market,history,costReport,csv,decimal,date,today,money,paid,used,sum,amount,tracksQuantity,activeProjects,CONSTRUCTION_SCOPES,constructionTotals,isContractor,contractFileData,CONTRACT_FILE_LIMIT} from './domain.mjs?v=20261118-contractor3';
import {demo} from './demo.mjs?v=20261118-contractor3';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(n),pct=n=>n===null?'—':fmt(n*100)+'%',brDate=d=>d?d.slice(0,10).split('-').reverse().join('/'):'—',val=(n,d=100)=>String(n/d);
const icons={overview:'◫',project:'⌂',costs:'≡',contractors:'♧',stages:'▦',documents:'▱',diary:'▧',reminders:'◷',profit:'↗',market:'⌕',history:'↔'};
const pages={overview:'Visão geral',project:'Empreendimento',costs:'Custos e pagamentos',contractors:'Empreiteiro',stages:'Etapas e materiais',documents:'Documentos e projetos',diary:'Diário de obra · fotos',reminders:'Agenda e lembretes',profit:'Viabilidade e lucro',market:'Mercado da região',history:'Histórico e comparativo'};
let mode=localStorage.getItem('ss-workspace')||'workspace',key=()=>`solucao-sobrados-v1-${mode}`,state,page='overview',selected='',costFilter={stage:'',kind:'',search:'',unit:''},marketFilter={condition:'new',includeUnknownZone:false,unitId:''},years={a:'2024',b:'2026'},tabError='';
let disposeDiary=null,disposeReminders=null,disposePhoto=null;
const projects=()=>activeProjects(state);
function load(){const raw=localStorage.getItem(key());state=raw?validate(JSON.parse(raw)):mode==='demo'?demo():empty();let migrated=false;for(const p of state.projects){if(!p.diaryKey){p.diaryKey=crypto.randomUUID();migrated=true;}}if(migrated&&raw)state.revision++;if(!raw||migrated)localStorage.setItem(key(),JSON.stringify(state));if(!projects().some(p=>p.id===selected))selected=projects()[0]?.id||'';}
const current=()=>projects().find(p=>p.id===selected);
function toast(message,error=false){$('#notice').textContent=message;$('#notice').className=error?'error':'';$('#notice').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#notice').hidden=true,6500);}
function save(type,payload){const stored=JSON.parse(localStorage.getItem(key())||'null');if(stored&&stored.revision!==state.revision)throw new Error('Os dados mudaram em outra aba. Clique em Atualizar e revise o lançamento.');const out=command(state,type,payload);try{localStorage.setItem(key(),JSON.stringify(out.state));}catch(err){if(err.name==='QuotaExceededError')throw new Error('O armazenamento deste navegador está cheio. O registro não foi salvo. Tente um contrato com arquivo menor ou sem anexo.');throw err;}state=out.state;if(type==='contractor.save')page='contractors';if(type==='project.create'||type==='project.restore'){selected=out.result.id;page='project';}if(type==='project.trash'){selected=projects()[0]?.id||'';page='overview';}render();toast(type==='project.trash'?'Empreendimento movido para a lixeira. Você pode restaurá-lo.':type==='project.restore'?'Empreendimento restaurado.':'Registro salvo neste navegador.');return out.result;}
function download(name,content,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const tag=(text,tone='')=>`<span class="tag ${tone}">${esc(text)}</span>`;
const btn=(action,label,id='',kind='')=>`<button class="btn ${kind}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const field=(name,label,value='',type='text',options='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${options}></label>`;
const number=(name,label,n,min=0,step='0.01')=>field(name,label,n,'number',`min="${min}" step="${step}" required`);
const select=(name,label,rows,value='')=>`<label>${label}<select name="${name}" aria-label="${esc(label)}">${rows.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const area=(name,label,value='')=>`<label class="wide">${label}<textarea name="${name}" rows="2">${esc(value)}</textarea></label>`;
const check=(name,label,checked=false)=>`<label class="check wide"><input type="checkbox" name="${name}" ${checked?'checked':''}>${label}</label>`;
const choices=arr=>arr.map(x=>[x,x]);
const emptyView=(title,copy,action='')=>`<div class="empty"><div class="empty-mark">⌂</div><h3>${title}</h3><p>${copy}</p>${action}</div>`;
function dialog(title,body,onSave,label='Salvar'){const dlg=$('#dialog');dlg.innerHTML=`<form id="editor"><div class="dialog-head"><div><span class="eyebrow">SOLUÇÃO SOBRADOS</span><h2>${title}</h2></div><button type="button" class="icon-btn" id="close" aria-label="Fechar">×</button></div><div class="form-grid">${body}</div><p class="form-error" id="form-error" role="alert" tabindex="-1"></p><div class="dialog-footer"><button type="button" class="btn" id="cancel">Cancelar</button><button class="btn primary" type="submit">${label}</button></div></form>`;$('#close').onclick=$('#cancel').onclick=()=>dlg.close();$('#editor').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await onSave(new FormData(e.target));dlg.close();}catch(err){$('#form-error').textContent=err.message;e.submitter.disabled=false;$('#form-error').focus();}};dlg.showModal();}
function title(kicker,heading,copy,buttons=''){return `<header class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${heading}</h1><p class="subtitle">${copy}</p></div><div class="actions">${buttons}</div></header>`;}
function metric(label,value,foot,tone=''){return `<article class="metric ${tone}"><span>${label}</span><strong>${value}</strong><small>${foot}</small></article>`;}
function projectionNotice(p){const n=p.stages.filter(st=>st.budget===0&&!p.expenses.some(e=>!e.cancelled&&e.stageId===st.id)).length;return p.status!=='closed'&&n?`<div class="callout projection-notice"><strong>Projeção ainda parcial: ${n} etapas sem orçamento nem custos.</strong> Cadastre o custo final esperado de cada etapa aplicável antes de usar a margem para decidir o preço. Itens ainda não informados não entram no cálculo.</div>`:'';}
function render(){
  disposeDiary?.();disposeDiary=null;disposeReminders?.();disposeReminders=null;disposePhoto?.();disposePhoto=null;
  const p=current();document.title=`Solução Sobrados · ${pages[page]}`;
  $('#app').innerHTML=`<aside class="sidebar"><a class="logo" href="#" data-action="overview"><span class="logo-mark">⌂</span><span>SOLUÇÃO<strong>SOBRADOS</strong></span></a><p class="sidebar-sub">Da primeira medida ao resultado.</p><div class="workspace-label">SEU ESCRITÓRIO</div><nav>${Object.entries(pages).map(([id,name])=>`<button class="nav-item ${page===id?'active':''}" data-action="nav" data-id="${id}" ${!p&&id!=='overview'?'disabled':''}><span>${icons[id]}</span>${name}${page===id?'<i>●</i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="location-icon">↗</div><strong>Feito para Praia Grande</strong><p>Um olhar completo para cada sobrado.</p><span class="version">AMBIENTE DE TESTES · V1</span></div></aside><div class="main-shell"><header class="topbar"><div class="project-identity"><span id="project-photo" class="project-photo" title="Empreendimento sem foto definida">⌂</span><div class="project-selector"><span>Empreendimento</span><select id="project-select" aria-label="Selecionar empreendimento">${p?projects().map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join(''):'<option>Crie seu primeiro empreendimento</option>'}</select></div></div><div class="top-actions">${btn('refresh','↻ Atualizar')}${btn('backup','↓ Backup')}${btn('project-trash-list','Lixeira ('+(state.projects.length-projects().length)+')')}${btn('import','Restaurar')}${btn('workspace',mode==='demo'?'Minha base vazia':'Ver exemplos')}<span class="avatar" title="Testes locais">SS</span></div></header><div class="test-strip"><span class="dot"></span>${mode==='demo'?'EXEMPLOS FICTÍCIOS':'BASE DE TESTES'} · Sem senha. Custos neste navegador; fotos, documentos e lembretes online quando ativados. Faça backup dos custos.</div><div id="reminder-summary" class="reminder-summary"></div><main id="main">${!p?title('COMECE PELO EMPREENDIMENTO','Uma obra organizada começa aqui.','Cadastre o terreno, as unidades e o formato de contratação. Depois, acompanhe cada custo até a entrega.',btn('project-new','+ Novo empreendimento','','primary'))+emptyView('Seu próximo sobrado, com os números em dia.','Nenhuma obra cadastrada nesta base. Os exemplos continuam disponíveis em “Ver exemplos”.'):({overview:overview,project:projectPage,costs:costsPage,contractors:contractorsPage,stages:stagesPage,documents:()=>'<div id="diary-section"></div>',diary:()=>'<div id="diary-section"></div>',reminders:()=>'<div id="diary-section"></div>',profit:profitPage,market:marketPage,history:historyPage}[page])(p)}</main><footer class="app-footer"><span>Solução Sobrados</span><span>Independente do Moove ON · ${projects().length} empreendimentos nesta base</span></footer></div><datalist id="categories">${CATEGORIES.map(x=>`<option value="${x}">`).join('')}</datalist><datalist id="neighborhoods">${NEIGHBORHOODS.map(x=>`<option value="${x}">`).join('')}</datalist>`;
  if(p)disposePhoto=mountProjectIdentity($('#project-photo'),p.diaryKey);
  if(['diary','reminders','documents'].includes(page)&&p){try{disposeDiary=mountDiary({container:$('#diary-section'),project:p,contextKey:p.diaryKey,view:page==='documents'?'documents':page==='reminders'?'reminders':'photos'});}catch(e){$('#diary-section').textContent='Não foi possível abrir o diário: '+e.message;}}
  if(p&&!['diary','reminders','documents'].includes(page))disposeReminders=mountReminderSummary($('#reminder-summary'),p.diaryKey);
  $('#project-select').onchange=e=>{selected=e.target.value;costFilter={stage:'',kind:'',search:'',unit:''};marketFilter.unitId='';render();};
  $('#app').onclick=e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();try{act(el.dataset.action,el.dataset.id);}catch(err){toast(err.message,true);}}};
  const cf=$('#cost-filters');if(cf)cf.onsubmit=e=>{e.preventDefault();costFilter=Object.fromEntries(new FormData(cf));render();};
  const mf=$('#market-filters');if(mf)mf.onchange=()=>{const d=new FormData(mf);marketFilter={condition:d.get('condition'),unitId:d.get('unitId'),includeUnknownZone:d.has('includeUnknownZone')};render();};
  const hf=$('#history-filters');if(hf)hf.onsubmit=e=>{e.preventDefault();years=Object.fromEntries(new FormData(hf));render();};
}
function overview(p){const t=totals(p),progress=t.budget?sum(t.stages,x=>x.progress*x.budget)/t.budget:0,over=t.stages.filter(st=>st.contracted>st.budget),extras=p.expenses.filter(e=>!e.cancelled&&e.kind==='extra');
  return title('VISÃO GERAL / PRAIA GRANDE',`Cada etapa sob controle.<br><span class="light-heading">Cada real no seu resultado.</span>`,`${esc(p.name)} · ${esc(p.neighborhood)} · ${esc(p.zone)} · ${p.units.length} unidades`,btn('project-new','+ Empreendimento')+btn('expense-quick','+ Gasto rápido','','primary')+btn('expense-new','Lançamento detalhado'))+
  projectionNotice(p)+`<div class="metrics">${metric('Custo final previsto',money(t.forecast),'Orçamento por etapa + excedentes + reserva','teal')}${metric('Já saiu do caixa',money(t.paid),money(t.pending)+' contratado a pagar')}${metric('Lucro previsto',money(t.profit),'Após custos e despesas de venda',t.profit>=0?'green':'rose')}${metric('Margem prevista',pct(t.margin),'Meta: '+fmt(p.targetBps/100)+'% da receita','sand')}</div>
  <div class="dashboard-grid"><section class="card budget-card"><div class="section-head"><div><span class="eyebrow">A OBRA EM NÚMEROS</span><h2>Do terreno à entrega</h2></div>${tag(p.status==='closed'?'Obra encerrada':'Em andamento',p.status==='closed'?'green':'blue')}</div><div class="budget-total"><strong>${money(t.contracted)}</strong><span>em custos contratados / incorridos</span></div><div class="stacked"><span style="width:${t.forecast?Math.min(100,t.paid/t.forecast*100):0}%" class="paid"></span><span style="width:${t.forecast?Math.min(100-t.paid/t.forecast*100,t.pending/t.forecast*100):0}%" class="pending"></span></div><div class="legend"><span><i class="green-dot"></i>Pago ${money(t.paid)}</span><span><i class="sand-dot"></i>A pagar ${money(t.pending)}</span><span><i class="gray-dot"></i>Restante previsto ${money(t.forecast-t.contracted)}</span></div><div class="mini-stats"><div><strong>${fmt(t.area)} m²</strong><span>Área privativa total</span></div><div><strong>${money(t.costPerSqm)}/m²</strong><span>Custo completo previsto</span></div><div><strong>${fmt(progress)}%</strong><span>Avanço informado¹</span></div></div><p class="fine">¹ Ponderado pelo orçamento das etapas. Avanço físico informado pela equipe, sem inferir progresso pelos pagamentos.</p></section>
  <section class="result-card"><span class="eyebrow">ONDE VOCÊ QUER CHEGAR</span><h2>Uma boa obra também<br>precisa fechar a conta.</h2><div class="result-value">${money(t.revenue)}</div><p>Receita de venda estimada · ${p.units.length} unidades</p><div class="result-row"><span>Despesas de venda</span><strong>${money(t.selling)}</strong></div><div class="result-row"><span>Reserva para imprevistos</span><strong>${money(t.reserve)}</strong></div>${btn('nav','Ver viabilidade ↗','profit','white')}<span class="building-art" aria-hidden="true">▥ ▥ ▥</span></section></div>
  <div class="dashboard-grid bottom-grid"><section class="card"><div class="section-head"><div><span class="eyebrow">OLHAR POR UNIDADE</span><h2>O custo de cada sobrado</h2></div>${btn('nav','Ver todas →','project')}</div><div class="unit-summary">${t.units.slice(0,4).map(u=>`<article><div class="house-icon">⌂</div><div><strong>${esc(u.name)}</strong><small>${fmt(u.area/100)} m²</small></div><div><strong>${money(u.forecast)}</strong><small>Margem ${pct(u.margin)}</small></div></article>`).join('')}</div></section><section class="card"><div class="section-head"><div><span class="eyebrow">SUA ATENÇÃO AQUI</span><h2>Antes do próximo passo</h2></div>${tag('Acompanhamento','sand')}</div><div class="attention"><span class="attention-icon sand">!</span><div><strong>${over.length} etapa(s) acima do orçamento</strong><p>Revise a previsão restante para manter o lucro visível.</p></div></div><div class="attention"><span class="attention-icon blue">↗</span><div><strong>${extras.length} despesas extras registradas</strong><p>Inclusive serviços fora do padrão, com descrição no relatório final.</p></div></div><div class="attention"><span class="attention-icon green">✓</span><div><strong>O custo comum aparece em cada unidade</strong><p>Rateio ${p.allocation==='area'?'por área':'igualitário'}. Valores já lançados mantêm sua distribuição registrada.</p></div></div>${btn('report','Abrir relatório completo →')}</section></div>`;
}
function projectPage(p){const t=totals(p);return title('CADASTRO DO EMPREENDIMENTO',esc(p.name),`${esc(p.address||'Endereço não informado')} · ${esc(p.neighborhood)} · ${esc(p.zone)}`,btn('project-edit','Editar empreendimento')+btn('project-trash','Excluir empreendimento',p.id,'danger')+btn('project-new','+ Novo empreendimento','','primary'))+
  projectionNotice(p)+`<div class="project-facts card"><div><span>Formato</span><strong>${p.type==='condominium'?'Sobrados em condomínio':'Sobrado individual'}</strong></div><div><span>Início</span><strong>${brDate(p.start)}</strong></div><div><span>Tipologia</span><strong>${[...new Set(p.units.map(u=>u.bedrooms??p.bedrooms))].sort((a,b)=>a-b).join(' / ')} dormitórios</strong></div><div><span>Unidades / área</span><strong>${p.units.length} / ${fmt(t.area)} m²</strong></div><div><span>Rateio padrão</span><strong>${p.allocation==='area'?'Por área privativa':'Igual por unidade'}</strong></div></div>
  <section class="card"><div class="section-head"><div><h2>As unidades do empreendimento</h2><p>Custos diretos + participação nos custos comuns + previsão restante.</p></div>${p.status!=='closed'?btn('unit-add','+ Adicionar unidade'):''}${tag('Valores de venda estimados','blue')}</div><div class="units-grid">${t.units.map(u=>`<article class="unit-card"><div class="unit-top"><span class="house-icon">⌂</span>${tag(fmt(u.area/100)+' m²')}</div><h3>${esc(u.name)}</h3><p>${u.bedrooms??p.bedrooms} dormitórios${u.bathrooms!=null?' · '+u.bathrooms+' banheiros':''}${u.parking!=null?' · '+u.parking+' vagas':''}</p>${u.notes?'<p class="fine">'+esc(u.notes)+'</p>':''}<dl><div><dt>Custo contratado</dt><dd>${money(u.contracted)}</dd></div><div><dt>Custo final previsto</dt><dd>${money(u.forecast)}</dd></div><div><dt>Pago alocado</dt><dd>${money(u.paid)}</dd></div><div><dt>Venda estimada</dt><dd>${money(u.sale)}</dd></div><div class="unit-result"><dt>Lucro / margem</dt><dd>${money(u.profit)}<small>${pct(u.margin)}</small></dd></div></dl>${p.status!=='closed'?btn('unit-edit','Editar unidade',u.id):''}</article>`).join('')}</div><p class="fine">Alterar a área muda apenas os próximos rateios e a previsão não contratada. Custos existentes mantêm o rateio gravado; edite cada lançamento se precisar redistribuí-lo.</p></section><section class="card section-gap"><h2>Observações do empreendimento</h2><p>${esc(p.notes||'Nenhuma observação registrada.')}</p><div class="callout">Zona 1, 2 e 3 são classificações de localização informadas pela equipe para pesquisa de mercado. O cadastro não valida zoneamento urbanístico nem substitui consulta à Prefeitura.</div><div class="actions section-gap">${p.status==='closed'?btn('project-reopen','Reabrir obra com justificativa'):btn('project-close','Encerrar obra e conferir custos','','danger')}${btn('report','Relatório de fechamento')}</div></section>`;}
function filteredCosts(p){return p.expenses.filter(e=>!e.cancelled&&(!costFilter.stage||e.stageId===costFilter.stage)&&(!costFilter.kind||e.kind===costFilter.kind)&&(!costFilter.unit||(e.allocation[costFilter.unit]||0)>0)&&(!costFilter.search||[e.description,e.category,e.supplier].join(' ').toLowerCase().includes(costFilter.search.toLowerCase())));}
function costTable(p,rows,actions=true){return `<div class="table-scroll"><table><thead><tr><th>Lançamento / categoria</th><th>Etapa / destino</th><th>Quantidade</th><th>Contratado</th><th>Pago</th><th>Saldo</th>${actions?'<th>Ações</th>':''}</tr></thead><tbody>${rows.map(e=>`<tr><td><strong>${esc(e.description)}</strong><small>${esc(e.category)} · ${esc(e.supplier||'Sem fornecedor')}</small>${e.extraToContract?tag('Adicional fora da empreitada','sand'):''}</td><td>${esc(p.stages.find(st=>st.id===e.stageId).name)}<small>${e.mode==='direct'?esc(p.units.find(u=>u.id===e.unitId)?.name||'Unidade'):e.mode==='area'?'Comum · por área':'Comum · igualitário'}</small></td><td>${fmt(e.qty/1000)} ${esc(e.uom)}<small>${money(e.unitCents)} / ${esc(e.uom)}</small></td><td class="numeric">${money(e.total)}</td><td class="numeric">${money(paid(e))}</td><td class="numeric">${tag(money(e.total-paid(e)),paid(e)===e.total?'green':'sand')}</td>${actions?`<td><div class="row-actions">${btn('expense-detail','Ver',e.id)}${e.total>paid(e)&&p.status!=='closed'?btn('payment','Pagar',e.id):''}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function constructionPanel(p){
  const t=constructionTotals(p);
  const review=(rows,excluded)=>rows.length?`<div class="table-scroll"><table><thead><tr><th>Lançamento / categoria</th><th>Pago</th><th>Critério</th><th></th></tr></thead><tbody>${rows.map(({expense:e,reason})=>`<tr><td><strong>${esc(e.description)}</strong><small>${esc(e.category)}</small></td><td class="numeric">${money(paid(e))}</td><td>${esc(reason||(e.constructionScope==='included'?'Inclusão informada':'Construção pela categoria'))}</td><td>${p.status!=='closed'?btn('construction-classify','Classificar',e.id):''}</td></tr>`).join('')}</tbody></table></div>`:`<p>Nenhum lançamento ${excluded?'excluído':'incluído'}.</p>`;
  return `<section class="card quick-catalog" aria-label="Construção por casa e por m²"><div class="section-head"><div><span class="eyebrow">CONSTRUÇÃO POR METRAGEM</span><h2>Quanto custou construir cada casa?</h2><p>Valor já pago. Terreno, comissões e impostos são excluídos automaticamente; confira as classificações abaixo.</p></div></div>
  <div class="metrics">${metric('Construção já paga',money(t.paid),'Base do cálculo por área','teal')}${metric('Construção por m²',money(t.costPerSqm),'Construção paga ÷ área privativa')}${metric('Área total das casas',fmt(t.area)+' m²',p.units.length+' unidades cadastradas')}${metric('Pagos fora da construção',money(t.excludedPaid),'Confira as exclusões abaixo','sand')}</div>
  <p class="callout">${money(t.paid)} ÷ ${fmt(t.area)} m² = <strong>${money(t.costPerSqm)}/m²</strong>. O custo de cada casa é proporcional à sua metragem. O cálculo usa a precisão integral e distribui os centavos para fechar o total.</p>
  <div class="table-scroll"><table class="construction-units"><thead><tr><th>Casa</th><th>Metragem</th><th>Custo da construção</th></tr></thead><tbody>${t.units.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${fmt(u.area/100)} m²</td><td class="numeric">${money(u.constructionPaid)}</td></tr>`).join('')}</tbody><tfoot><tr><td><strong>Total</strong></td><td>${fmt(t.area)} m²</td><td class="numeric"><strong>${money(t.paid)}</strong></td></tr></tfoot></table></div>
  <p class="fine">Este quadro considera toda a obra, independentemente dos filtros abaixo. É uma distribuição analítica por área atual: os rateios diretos e comuns dos lançamentos permanecem no detalhamento e em Empreendimento. Não inclui orçamento futuro nem reserva. Construção contratada: ${money(t.contracted)}; ainda a pagar: ${money(t.pending)}.</p>
  <details class="quick-details"><summary>Conferir exclusões (${t.excluded.length} lançamentos)</summary><p class="fine">Automático: natureza Aquisição, categoria Terreno, comissões, impostos, tributos, IPTU, ITBI, ISS e INSS/FGTS. Projetos, água e luz continuam incluídos. Use Classificar para ajustar um lançamento.</p>${review(t.excluded,true)}</details>
  <details class="quick-details section-gap"><summary>Conferir construção incluída (${t.included.length} lançamentos)</summary>${review(t.included,false)}</details></section>`;
}
function constructionForm(p,e){dialog('Classificação no custo da construção',`<div class="callout wide"><strong>${esc(e.description)}</strong><br>${esc(e.category)} · Pago ${money(paid(e))}<br>Altera somente a participação neste cálculo por m²; preserva valores, pagamentos e rateios registrados.</div>`+select('constructionScope','Participação na construção',Object.entries(CONSTRUCTION_SCOPES),e.constructionScope||'auto'),f=>save('expense.construction',{projectId:p.id,id:e.id,constructionScope:f.get('constructionScope')}),'Salvar classificação');}
function costsPage(p){const rows=filteredCosts(p);return title('PLANILHA DE CUSTOS','Cada gasto, no lugar certo.','Materiais, mão de obra, terreno e imprevistos. Pagamentos parciais preservam o saldo de cada compromisso.',btn('export-costs','↓ Exportar CSV')+btn('expense-quick','+ Gasto rápido','','primary')+btn('expense-new','Lançamento detalhado'))+
  `${constructionPanel(p)}${p.status!=='closed'?quickCatalog():''}<section class="card"><form id="cost-filters" class="filters">${field('search','Buscar custo / fornecedor',costFilter.search)}${select('stage','Etapa',[['','Todas as etapas'],...p.stages.map(st=>[st.id,st.name])],costFilter.stage)}${select('kind','Natureza',[['','Todas'],...Object.entries(KINDS)],costFilter.kind)}${select('unit','Destino',[['','Todas as unidades'],...p.units.map(u=>[u.id,u.name])],costFilter.unit)}<button class="btn">Filtrar</button></form><div class="totals-line"><span>${rows.length} lançamentos</span><strong>Contratado ${money(sum(rows,'total'))}</strong><span>Pago ${money(sum(rows,paid))}</span><span>Saldo ${money(sum(rows,e=>e.total-paid(e)))}</span></div>${rows.length?costTable(p,rows):emptyView('Nenhum lançamento neste filtro.','Cadastre o custo e informe a etapa, a categoria e para quais unidades ele será rateado.')}${costFilter.unit?'<p class="callout">O filtro por unidade mostra os lançamentos que a atendem, com o valor integral do documento. A participação da unidade aparece em Empreendimento e no detalhamento.</p>':''}</section>`;}
function stagesPage(p){const t=totals(p),materials=p.expenses.filter(e=>!e.cancelled&&e.kind==='material'&&(tracksQuantity(e)||e.uses.length)),amountOnly=p.expenses.filter(e=>!e.cancelled&&e.kind==='material'&&!tracksQuantity(e));return title('DA FUNDAÇÃO AO ACABAMENTO','Etapas que contam a história da obra.','Compare o orçamento com o contratado e acompanhe a quantidade de material utilizada.',btn('stage-new','+ Etapa personalizada')+btn('expense-quick','+ Gasto rápido','','primary')+btn('expense-new','Lançamento detalhado'))+
  `<section class="card"><div class="section-head"><h2>Orçamento e execução por etapa</h2><span class="muted">Clique em Ajustar para informar orçamento e avanço físico</span></div><div class="table-scroll"><table><thead><tr><th>Etapa</th><th>Avanço informado</th><th>Orçado</th><th>Contratado</th><th>Pago</th><th>Previsão final¹</th><th></th></tr></thead><tbody>${t.stages.map(st=>`<tr><td><strong>${esc(st.name)}</strong>${st.contracted>st.budget?tag('Acima do orçamento','rose'):''}</td><td><div class="progress"><i style="width:${st.progress}%"></i></div><small>${st.progress}%</small></td><td class="numeric">${money(st.budget)}</td><td class="numeric">${money(st.contracted)}</td><td class="numeric">${money(st.paid)}</td><td class="numeric">${money(st.forecast)}</td><td>${btn('stage-edit','Ajustar',st.id)}</td></tr>`).join('')}</tbody></table></div><p class="fine">¹ Obra aberta: maior valor entre orçamento e contratado em cada etapa. A reserva é adicionada no total geral. Etapas encerradas precisam ter seu orçamento revisado para refletir a previsão final. Obra encerrada usa apenas custos registrados.</p></section>
  <section class="card section-gap"><div class="section-head"><div><h2>Materiais: compra e consumo</h2><p>Consumo é uma informação de uso; não cria outro custo nem altera o rateio financeiro da compra.</p></div></div>${amountOnly.length?`<div class="callout"><strong>${amountOnly.length} gasto(s) de material informado(s) somente por valor.</strong> Eles já estão nos custos. Para controlar consumo, edite o mesmo lançamento e informe quantidade física e medida, preservando o valor total. Não crie outra compra. Registros antigos de uso em verba permanecem no histórico abaixo.</div><div class="actions section-gap">${amountOnly.map(e=>btn(p.status==='closed'||e.uses.length?'expense-detail':'expense-edit',esc(e.description)+(p.status==='closed'||e.uses.length?' · Ver custo':' · Informar quantidade'),e.id)).join('')}</div>`:''}${materials.length?`<div class="table-scroll"><table><thead><tr><th>Material</th><th>Comprado</th><th>Utilizado</th><th>Disponível</th><th>Onde foi usado</th><th></th></tr></thead><tbody>${materials.map(e=>`<tr><td><strong>${esc(e.description)}</strong><small>${esc(e.uom)} · ${money(e.unitCents)} por medida</small></td><td>${fmt(e.qty/1000)}</td><td>${fmt(used(e)/1000)}</td><td>${fmt((e.qty-used(e))/1000)}</td><td>${e.uses.map(u=>`<small>${esc(p.stages.find(st=>st.id===u.stageId).name)} · ${fmt(u.qty/1000)} ${esc(e.uom)}${u.unitId?' · '+esc(p.units.find(x=>x.id===u.unitId).name):''}</small>`).join('')||'Sem consumo registrado'}</td><td>${!tracksQuantity(e)?tag('Histórico sem medida física','sand'):p.status!=='closed'?btn('material-use','Registrar uso',e.id):''}</td></tr>`).join('')}</tbody></table></div>`:emptyView('Nenhum material com quantidade física.','Informe sacos, quilos, metros ou outra medida no lançamento detalhado para acompanhar o consumo.')}</section>`;}
function profitPage(p){const t=totals(p);return title('VIABILIDADE DO EMPREENDIMENTO','A obra precisa caber no resultado.','Cenários de venda para entender sua margem antes de tomar a próxima decisão.',btn('project-edit','Ajustar premissas')+btn('report','Relatório completo','','primary'))+
  projectionNotice(p)+`<div class="metrics">${metric('Venda total estimada',money(t.revenue),p.units.length+' unidades')}${metric('Custo final previsto',money(t.forecast),'Inclui '+money(t.reserve)+' de reserva','teal')}${metric('Lucro previsto',money(t.profit),'Receita − custos − despesas de venda',t.profit>=0?'green':'rose')}${metric('Margem sobre a venda',pct(t.margin),'Retorno sobre custo total: '+pct(t.returnOnCost),'sand')}</div><div class="dashboard-grid"><section class="card"><h2>A conta aberta, sem surpresas</h2><div class="waterfall"><div><span>Receita de venda estimada</span><strong>${money(t.revenue)}</strong></div><div><span>Custos previstos por etapa</span><strong>− ${money(t.base)}</strong></div><div><span>Reserva · ${p.status==='closed'?'não aplicada à obra encerrada':fmt(p.reserveBps/100)+'% sobre o custo base'}</span><strong>− ${money(t.reserve)}</strong></div><div><span>Comissão e outras despesas de venda · ${fmt(p.sellingBps/100)}%</span><strong>− ${money(t.selling)}</strong></div><div class="total"><span>Lucro previsto</span><strong>${money(t.profit)}</strong></div></div><p class="fine">As taxas são premissas informadas pela equipe, não alíquotas oficiais. Tributos e outros custos precisam estar lançados. Venda estimada não representa contrato assinado nem recebimento.</p></section><section class="card"><span class="eyebrow">SEUS PONTOS DE REFERÊNCIA</span><h2>Por quanto precisa vender?</h2><div class="target"><span>Para cobrir custos e despesas de venda</span><strong>${money(t.breakEven)}</strong><small>${money(Math.ceil(t.breakEven/p.units.length))} por unidade, média</small></div><div class="target"><span>Para atingir ${fmt(p.targetBps/100)}% de margem</span><strong>${money(t.targetRevenue)}</strong><small>${money(Math.ceil(t.targetRevenue/p.units.length))} por unidade, média</small></div>${btn('nav','Comparar com anúncios da região →','market')}</section></div><section class="card section-gap"><div class="section-head"><h2>Se o valor de venda mudar…</h2><span class="muted">Custos mantidos; despesas de venda variam com a receita</span></div><div class="scenario-grid">${[[-1000,'Conservador','Venda 10% menor'],[0,'Planejado','Seu preço atual'],[1000,'Otimista','Venda 10% maior']].map(([bps,label,help])=>{const x=scenario(p,bps);return `<article class="scenario ${bps===0?'selected':''}"><span>${label}</span><small>${help}</small><strong>${money(x.profit)}</strong><span>lucro previsto</span>${tag(pct(x.margin)+' de margem',x.profit>=0?'green':'rose')}<p>Receita ${money(x.revenue)}</p></article>`;}).join('')}</div></section>`;}
function marketPage(p){const unit=p.units.find(u=>u.id===marketFilter.unitId)||p.units[0],m=market(state,p,{...marketFilter,area:unit.area,bedrooms:unit.bedrooms??p.bedrooms}),query=`sobrado ${p.type==='condominium'?'em condomínio':''} ${unit.bedrooms??p.bedrooms} dormitórios ${p.neighborhood} ${p.zone} Praia Grande ${fmt(unit.area/100)} m² venda`;
 return title('REFERÊNCIAS DE MERCADO','Seu preço, com contexto.','Compare anúncios semelhantes. O preço pedido ajuda no planejamento, mas não confirma o valor de uma venda.',`<a class="btn" href="https://www.google.com/search?q=${encodeURIComponent(query)}" target="_blank" rel="noopener noreferrer">Buscar anúncios ↗</a>`+btn('comparable-new','+ Registrar referência','','primary'))+
 `<section class="card"><form id="market-filters" class="filters">${select('unitId','Unidade de referência',p.units.map(u=>[u.id,`${u.name} · ${fmt(u.area/100)} m²`]),unit.id)}${select('condition','Condição do imóvel',[['new','Novo'],['used','Usado / reformado'],['all','Todas as condições']],marketFilter.condition)}${check('includeUnknownZone','Incluir anúncios com zona não informada',marketFilter.includeUnknownZone)}</form><p class="fine">Recorte: ${esc(p.neighborhood)} · ${esc(p.zone)} · ${unit.bedrooms??p.bedrooms} dormitórios · ${p.type==='condominium'?'condomínio':'individual'} · área ±25% · consulta até 90 dias. Bairro e zona são declarados; sem geolocalização automática.</p><div class="metrics three">${metric('Referências compatíveis',String(m.rows.length),'De '+m.examined.length+' anúncios cadastrados')}${metric('Mediana por m²',m.median?money(m.median):'Amostra insuficiente','Mínimo de 3 referências compatíveis','teal')}${metric('Indicação para esta área',m.estimate?money(m.estimate):'Complete a pesquisa',m.estimate?'Faixa observada: '+money(m.min)+' a '+money(m.max):'Nenhum preço será aplicado automaticamente','sand')}</div><div class="callout">A busca abre a pesquisa na web. Registre os anúncios conferidos com link e data; esta versão não coleta nem atualiza portais automaticamente. A mediana é uma referência simples de preços anunciados, sem laudo de avaliação. Confira duplicidades do mesmo imóvel entre imobiliárias.</div></section>
 <section class="section-gap"><div class="section-head"><h2>Referências e fontes</h2><span class="muted">Cada anúncio informa se entra na comparação</span></div><div class="market-grid">${m.examined.map(c=>`<article class="card market-card"><div class="section-head">${tag(c.reasons.length?'Fora do recorte':'Incluído',c.reasons.length?'sand':'green')}<span class="muted">${brDate(c.date)}</span></div><h3>${esc(c.title)}</h3><strong class="asking-price">${money(c.price)}</strong><p>${fmt(c.area/100)} m² · ${c.bedrooms} dormitórios · ${esc(c.zone)}</p><p class="muted">${esc(c.source)} · ${money(Math.round(c.rate))}/m²</p><p>${esc(c.notes)}</p>${c.reasons.length?`<p class="exclusion">${esc(c.reasons.join(' · '))}</p>`:''}<div class="actions"><a class="btn" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Abrir fonte ↗</a>${btn('comparable-edit','Conferir / editar',c.id)}</div></article>`).join('')||emptyView('Comece sua pesquisa.','Busque sobrados com características parecidas e registre as referências verificadas.')}</div></section>`;
}
function historyPage(p){const rows=history(state,years.a,years.b),allYears=[...new Set(projects().flatMap(p=>p.expenses.map(e=>e.date.slice(0,4))))].sort();return title('APRENDIZADO ENTRE EMPREENDIMENTOS','A próxima obra começa mais informada.','Compare preços unitários e custos completos. Valores nominais, sem correção pela inflação.',btn('history-export','↓ Exportar comparativo'))+
 `<section class="card"><div class="section-head"><h2>Preço da mesma especificação ao longo dos anos</h2></div><form class="filters" id="history-filters">${select('a','Ano de referência',choices(allYears),years.a)}${select('b','Ano de comparação',choices(allYears),years.b)}<button class="btn">Comparar</button></form><p class="fine">Agrupa descrição, natureza e unidade de medida iguais; preço médio ponderado pela quantidade contratada. Exclui terreno, taxas e valores globais em verba, lote ou contrato; compare o escopo completo na tabela de empreendimentos. Mantenha as especificações consistentes. Compras de qualidade ou escopo diferentes devem ter descrições diferentes.</p><div class="table-scroll"><table><thead><tr><th>Material / serviço</th><th>Medida</th><th>${years.a} · preço médio</th><th>${years.b} · preço médio</th><th>Variação nominal</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${KINDS[r.kind]}</small></td><td>${esc(r.uom)}</td><td>${r.priceA!==null?money(Math.round(r.priceA)):'Sem registros'}</td><td>${r.priceB!==null?money(Math.round(r.priceB)):'Sem registros'}</td><td>${r.change!==null?tag((r.change>0?'+':'')+pct(r.change),r.change>0?'rose':'green'):'—'}</td></tr>`).join('')}</tbody></table></div></section>
 <section class="card section-gap"><h2>Comparativo dos empreendimentos</h2><p class="fine">Obras abertas mostram previsão. Encerradas mostram os custos efetivamente registrados. Venda e lucro continuam estimados; não há recebimentos de vendas nesta versão.</p><div class="table-scroll"><table><thead><tr><th>Empreendimento / início</th><th>Situação</th><th>Área</th><th>Custo completo</th><th>Custo/m²</th><th>Mão de obra¹</th><th>Participação da mão de obra</th><th>Lucro estimado</th></tr></thead><tbody>${projects().map(p=>{const t=totals(p),labor=sum(p.expenses.filter(e=>!e.cancelled&&e.kind==='labor'),'total');return `<tr><td><strong>${esc(p.name)}</strong><small>${brDate(p.start)}</small></td><td>${tag(p.status==='closed'?'Encerrada':'Em andamento',p.status==='closed'?'green':'blue')}</td><td>${fmt(t.area)} m²</td><td>${money(t.forecast)}</td><td>${money(t.costPerSqm)}</td><td>${money(labor)}</td><td>${t.contracted?pct(labor/t.contracted):'—'}</td><td>${money(t.profit)}</td></tr>`;}).join('')}</tbody></table></div><p class="fine">¹ Mão de obra contratada / custos contratados. A comparação inclui terreno, padrão, localização e fases diferentes: não isola inflação ou produtividade.</p></section><section class="card section-gap"><h2>Histórico de alterações desta obra</h2><div class="audit-list">${state.audit.filter(a=>a.projectId===p.id).slice(-15).reverse().map(a=>`<div><span>${brDate(a.date)} · ${esc(actionName(a.type))}</span><strong>${esc(a.description||'Registro financeiro atualizado')}</strong></div>`).join('')}</div></section>`;}
function actionName(type){return ({'project.trash':'Empreendimento movido para a lixeira','project.restore':'Empreendimento restaurado','project.create':'Empreendimento criado','project.update':'Premissas atualizadas','unit.add':'Unidade adicionada','expense.quick':'Gasto rápido registrado','contractor.save':'Contrato de empreiteiro registrado / atualizado','expense.construction':'Classificação da construção atualizada','unit.save':'Unidade atualizada','stage.save':'Etapa / orçamento atualizado','expense.save':'Custo registrado / atualizado','expense.cancel':'Custo cancelado','payment.add':'Pagamento registrado','payment.reverse':'Pagamento estornado','material.use':'Consumo de material','project.close':'Obra encerrada','project.reopen':'Obra reaberta','comparable.save':'Referência de mercado'})[type]||type;}
function projectForm(p){
  const basics=field('name','Nome do empreendimento',p?.name||'','text','required maxlength="150"')+field('neighborhood','Bairro',p?.neighborhood||'Vila Tupi','text','required list="neighborhoods"')+select('zone','Zona de localização',choices(['Zona 1','Zona 2','Zona 3','Não informada']),p?.zone||'Zona 2')+select('type','Tipo do imóvel',[['condominium','Sobrados em condomínio'],['individual','Sobrado individual']],p?.type||'condominium')+field('address','Endereço',p?.address||'')+field('start','Início / aquisição',p?.start||today(),'date','required')+number('bedrooms','Dormitórios sugeridos para novas unidades',p?.bedrooms||2,1,'1')+select('allocation','Rateio padrão de custos comuns',[['area','Por área privativa'],['equal','Igual por unidade']],p?.allocation||'area');
  const initial=p?'':`<h3 class="wide form-section">As unidades e o terreno</h3><p class="wide fine">Cada casa pode ter medidas, dormitórios e preço próprios. Os valores abaixo são sugestões para campos ainda não personalizados.</p>${number('count','Quantidade inicial de unidades',7,1,'1')}${number('area','Área sugerida (m²)',62,.01)}${number('sale','Venda sugerida (R$)',0)}<div class="wide"><button type="button" class="btn" id="resize-units" aria-controls="unit-rows">Ajustar quantidade de unidades</button><button type="button" class="btn" id="undo-units" hidden>Desfazer ajuste</button><p class="fine">Ajusta a lista ao número informado. As sugestões preenchem os campos ainda não personalizados. Você pode desfazer o último ajuste antes de salvar.</p><p id="unit-feedback" class="callout" role="status" tabindex="-1" hidden></p></div><div id="unit-rows" class="wide unit-editor-list"></div>${number('land','Valor do terreno (R$)',0)}${number('commission','Comissão da aquisição (R$)',0)}${number('taxes','Impostos / taxas iniciais (R$)',0)}${check('acquisitionPaid','Terreno, comissão e impostos acima já foram pagos na data inicial')}<p class="fine wide">Os valores entram uma única vez na planilha de custos. Sem a marcação de pagamento, ficam contratados a pagar. As características de cada unidade também poderão ser editadas depois.</p><h3 class="wide form-section">Como será contratada a mão de obra?</h3>${select('laborMode','Formato',[['separate','Serviços separados / cadastrar depois'],['sqm','Empreitada por m²'],['fixed','Empreitada com valor fechado']],'separate')}${number('laborRate','Preço por m² ou valor fechado (R$)',0)}${field('coverage','Serviços incluídos na empreitada (separados por vírgula)','Pedreiro,Servente')}${area('laborNotes','Escopo e observações da contratação','')}<p class="fine wide">Por m²: preço × soma da área privativa das unidades. Áreas comuns contratadas além dessa base devem ser incluídas ao editar a quantidade da empreitada. Serviços cobertos não devem ser lançados novamente.</p>`;
  dialog(p?'Editar empreendimento':'Novo empreendimento',basics+initial+`<h3 class="wide form-section">Premissas de viabilidade</h3>${number('reserveBps','Reserva para imprevistos (%)',p?val(p.reserveBps):5)}${number('sellingBps','Despesas sobre a venda (%)',p?val(p.sellingBps):0)}${number('targetBps','Margem de lucro desejada (%)',p?val(p.targetBps):20)}<p class="fine wide">Despesas de venda incluem o percentual que você informar para comissão e outras despesas. Não há alíquota oficial pré-preenchida. A reserva incide sobre todo o custo previsto.</p>${area('notes','Anotações',p?.notes||'')}`,f=>{const d=Object.fromEntries(f);for(const k of ['reserveBps','sellingBps','targetBps'])d[k]=decimal(d[k]);d.bedrooms=Number(d.bedrooms);if(p){d.projectId=p.id;save('project.update',d);}else{for(const k of ['area','sale','land','commission','taxes','laborRate'])d[k]=decimal(d[k]);d.units=readUnitRows();if(Number(d.count)!==d.units.length)throw new Error('A quantidade informada difere das unidades abaixo. Use Ajustar para acrescentar ou Remover em cada linha.');d.count=d.units.length;d.acquisitionPaid=f.has('acquisitionPaid');save('project.create',d);}});
  if(!p){
    const form=$('#editor'),host=$('#unit-rows'),feedback=$('#unit-feedback'),undo=$('#undo-units');
    let unitRowSeq=0,previous=null;
    const rows=()=>[...host.children];
    const announce=message=>{feedback.textContent=message;feedback.hidden=false;feedback.focus();};
    const numberRows=()=>rows().forEach((row,i)=>row.querySelector('legend').textContent='Casa / unidade '+(i+1));
    const snapshot=()=>{previous=rows().map(row=>({row,fields:[...row.querySelectorAll('input')].map(input=>({input,value:input.value,defaultValue:input.defaultValue}))}));undo.hidden=false;};
    const suggestions=()=>({area:form.elements.area.value,bedrooms:form.elements.bedrooms.value,sale:form.elements.sale.value});
    const add=()=>{const taken=new Set(rows().map(row=>row.querySelector('[data-unit="name"]').value.trim().toLowerCase()));let n=1;while(taken.has(('Unidade '+String(n).padStart(2,'0')).toLowerCase()))n++;host.insertAdjacentHTML('beforeend',unitRow(unitRowSeq++,{name:'Unidade '+String(n).padStart(2,'0'),...suggestions()}));};
    for(let i=0;i<Number(form.elements.count.value);i++)add();
    $('#resize-units').onclick=()=>{
      const n=Number(form.elements.count.value);
      if(!Number.isInteger(n)||n<1||n>100){announce('Informe de 1 a 100 unidades.');return;}
      for(const name of ['area','bedrooms','sale'])if(!form.elements[name].reportValidity())return;
      snapshot();const removed=Math.max(0,host.children.length-n),defaults=suggestions();
      while(host.children.length>n)host.lastElementChild.remove();
      for(const row of rows())for(const [key,value] of Object.entries(defaults)){const input=row.querySelector('[data-unit="'+key+'"]');if(input.value===input.defaultValue){input.value=value;input.defaultValue=value;}}
      while(host.children.length<n)add();
      numberRows();$('#form-error').textContent='';
      announce(n+' unidade(s) na lista abaixo.'+(removed?' '+removed+' unidade(s) retirada(s); use Desfazer ajuste para recuperá-las.':'')+' Os campos personalizados foram preservados.');
    };
    undo.onclick=()=>{if(!previous)return;for(const item of previous)for(const field of item.fields){field.input.defaultValue=field.defaultValue;field.input.value=field.value;}host.replaceChildren(...previous.map(item=>item.row));form.elements.count.value=previous.length;previous=null;undo.hidden=true;numberRows();announce('A lista anterior foi recuperada. '+host.children.length+' unidade(s).');};
    host.onclick=e=>{const button=e.target.closest('[data-remove-unit]');if(!button)return;if(host.children.length===1){announce('Mantenha ao menos uma unidade.');return;}snapshot();button.closest('.unit-editor').remove();form.elements.count.value=host.children.length;numberRows();announce('Unidade retirada. '+host.children.length+' unidade(s) na lista. Você pode desfazer o ajuste.');};
  }
}
function unitRow(i,u){return `<fieldset class="unit-editor"><legend>Casa / unidade ${i+1}</legend><div class="form-grid">${field('uname'+i,'Identificação',u.name,'text','required maxlength="100" data-unit="name"')}${field('uarea'+i,'Área privativa (m²)',u.area,'number','required min="0.01" step="0.01" data-unit="area"')}${field('ubed'+i,'Dormitórios',u.bedrooms,'number','required min="1" max="10" step="1" data-unit="bedrooms"')}${field('usale'+i,'Venda estimada (R$)',u.sale,'number','required min="0" step="0.01" data-unit="sale"')}${field('ubath'+i,'Banheiros (opcional)','','number','min="0" max="20" step="1" data-unit="bathrooms"')}${field('uparking'+i,'Vagas (opcional)','','number','min="0" max="20" step="1" data-unit="parking"')}${field('unotes'+i,'Observações da unidade','','text','maxlength="2000" data-unit="notes"')}<button type="button" class="btn" data-remove-unit>Remover esta unidade</button></div></fieldset>`;}
function readUnitRows(){return [...document.querySelectorAll('.unit-editor')].map(row=>{const u=Object.fromEntries([...row.querySelectorAll('[data-unit]')].map(input=>[input.dataset.unit,input.value]));for(const k of ['area','sale'])u[k]=decimal(u[k]);u.bedrooms=Number(u.bedrooms);for(const k of ['bathrooms','parking'])u[k]=u[k]===''?null:Number(u[k]);return u;});}
function unitForm(p,u){dialog(u?'Editar unidade':'Adicionar unidade',field('name','Nome / identificação',u?.name||'','text','required maxlength="100"')+number('area','Área privativa (m²)',u?val(u.area):'',.01)+number('bedrooms','Dormitórios',u?.bedrooms??p.bedrooms,1,'1')+number('sale','Venda estimada (R$)',u?val(u.sale):0)+field('bathrooms','Banheiros (opcional)',u?.bathrooms??'','number','min="0" max="20" step="1"')+field('parking','Vagas (opcional)',u?.parking??'','number','min="0" max="20" step="1"')+area('notes','Observações da unidade',u?.notes||'')+`<p class="fine wide">Custos já registrados mantêm seu rateio. Novas unidades participam dos próximos rateios e da previsão restante. Confira a empreitada contratada caso a área total mude.</p>`,f=>{const d=Object.fromEntries(f);d.area=decimal(d.area);d.sale=decimal(d.sale);d.bedrooms=Number(d.bedrooms);for(const k of ['bathrooms','parking'])d[k]=d[k]===''?null:Number(d[k]);save(u?'unit.save':'unit.add',{...d,projectId:p.id,...(u?{id:u.id}:{})});});}


