function quickCatalog(){return `<section class="card quick-catalog"><div class="section-head"><div><h2>O que você gastou hoje?</h2><p>Escolha um item, informe o valor e indique se já foi pago. Você pode mudar o nome e a categoria.</p></div></div><div class="quick-items">${COST_SHORTCUTS.map((x,i)=>btn('expense-quick',esc(x[0]),String(i))).join('')}${btn('expense-quick','+ Outro gasto')}</div></section>`;}
const expenseStageOptions=p=>[['','Não informar'],...p.stages.filter(st=>!st.unassigned).map(st=>[st.id,st.name])];
