  $('#editor').addEventListener('invalid',e=>{const details=e.target.closest('details');if(details)details.open=true;},true);
  const sync=()=>{const form=$('#editor'),paidNow=form.elements.paymentStatus.value==='paid';form.elements.method.disabled=!paidNow;form.elements.method.closest('label').hidden=!paidNow;form.elements.due.disabled=paidNow;form.elements.due.closest('label').hidden=paidNow;form.elements.unitId.disabled=form.elements.mode.value!=='direct';form.elements.unitId.closest('label').hidden=form.elements.mode.value!=='direct';};
  $('#editor').elements.paymentStatus.onchange=sync;$('#editor').elements.mode.onchange=sync;sync();
